import {RAD,clamp,lerp,V} from './constants.js';
import {rigDimensions,selectedArea} from './orc-sails.js';
import {sailFlow} from './sail-flow.js';
import {boatScale,boatProfile,beamRatio,headsailScale,isCertificateBoat} from './boats.js';
import {standingRigLayout} from './rig-layout.js';
import {sailDesign,measuredArea} from './sail-measures.js';
export const windSide=s=>-(Math.sign(Math.sin(s.windAngle*RAD))||1);
export const headsailSide=s=>windSide(s)*(s.wingOnWing&&s.foresail==='genoa'&&Math.abs(s.windAngle)>=135?-1:1);
const responseCache=new WeakMap();
export function rigResponse(s){const r=s.controls.rig,md=sailDesign('main',s),gd=sailDesign('genoa',s),ma=isCertificateBoat(s)&&!md.exploratory?boatProfile(s).areas.main:measuredArea('main',md),ga=isCertificateBoat(s)&&!gd.exploratory?boatProfile(s).areas.genoa:measuredArea('genoa',gd),fa=s.foresail==='genoa'?ga*headsailScale(s):selectedArea(s.foresail,s),key=[...Object.values(r),s.windSpeed,s.windAngle,s.boatSpeed,s.genoaSize,s.main,s.reef,s.foresail,fa,boatProfile(s).id,boatScale(s),md.P,gd.HLU,ma,ga,s.controls.main.sheet,s.controls[s.foresail]?.sheet,s.rigLoads],cached=responseCache.get(s);if(cached&&key.every((x,i)=>x===cached.key[i]))return cached.value;
 const k=boatScale(s),rig=rigDimensions(s),L=rig.ISP*k,flow=sailFlow(s),fractional=rig.foreFraction<.965,swept=standingRigLayout(s).lowerSweep>.12,mainFill=.16+.84*clamp(s.controls.main.sheet/100),foreFill=clamp((s.controls[s.foresail]?.sheet||0)/18),area=(s.main?ma*mainFill:0)+fa*foreFill,approximateSide=flow.q*area*.75*Math.abs(flow.direction[0]),sideLoad=Math.max(0,s.rigLoads?.side??approximateSide),backstayN=(600+115*r.backstay)*k*k,shroudN=(2800+145*r.shrouds)*k*k,preload=(1800+105*r.forestay)*k*k,bendingMoment=(fractional?.38:.25)*backstayN+.035*shroudN-.012*preload,prebend=.025+bendingMoment*L*L/(8*450000*k**4),overbend=1+(Math.max(0,prebend/k-.25)/.30)**2,forestayN=(preload+(fractional?.20:.50)*backstayN+(swept?.16:.025)*shroudN)/overbend,lateralStiffness=(5500+35000*r.shrouds/100)*k,tipDeflection=.65*Math.tanh(sideLoad/lateralStiffness/k/.65),rake=.02+backstayN/(110000*k*k)-preload/(600000*k*k),heightLoss=(rake*rake+.5*tipDeflection*tipDeflection)/Math.max(1,L)+Math.PI*Math.PI*prebend*prebend/(4*Math.max(1,L)),forestayLoad=Math.max(0,s.rigLoads?.forestay??(s.foresail==='genoa'?flow.q*fa*.75*foreFill:0)),sag=.008+.642*Math.tanh(forestayLoad*Math.hypot(L,rig.J*k)/(8*Math.max(200,forestayN))/k/.642),loadDirection=s.rigLoads?.foreDirection||flow.direction;
 const value={backstayN,forestayN,shroudN,sideLoad,forestayLoad,tipDeflection,prebend,rake,sag,heightLoss,heightScale:1-heightLoss/L,loadDirection,awa:flow.awa,fractional};responseCache.set(s,{key,value});return value;}
const mastCache=new WeakMap();
export function mastPoint(v,s){const r=rigResponse(s);let cached=mastCache.get(s);if(!cached||cached.response!==r){cached={response:r,points:new Map()};mastCache.set(s,cached);}if(cached.points.has(v))return [...cached.points.get(v)];const rig=rigDimensions(s),point=[windSide(s)*r.tipDeflection*v**1.8,1.2+rig.ISP*r.heightScale*v,rig.mastZ+r.prebend*4*v*(1-v)-r.rake*v];cached.points.set(v,point);return [...point];}
export function forestayPoint(v,s){const rig=rigDimensions(s),top=mastPoint(rig.foreFraction,s),base=[0,1,rig.mastZ+rig.J],response=rigResponse(s),axis=V.unit(V.sub(top,base)),wind=response.loadDirection;let direction=V.sub(wind,V.mul(axis,V.dot(wind,axis)));direction=V.unit(direction);return base.map((x,i)=>lerp(x,top[i],v)+direction[i]*response.sag*4*v*(1-v));}
export function spreaderEndpoints(s,side,h){const layout=standingRigLayout(s),a=mastPoint(h,s),width=h>.6?layout.upperSpreader:layout.lowerSpreader;return[a,[a[0]+side*width,a[1]+.08,a[2]-(h>.6?layout.upperSweep:layout.lowerSweep)]];}
export function shroudPath(s,side,N=32){const layout=standingRigLayout(s),stations=[0,.42,.71,1],top=mastPoint(1,s),a=spreaderEndpoints(s,side,.42)[1],b=spreaderEndpoints(s,side,.71)[1],anchors=[[side*layout.chainplateX,.91,layout.shroudZ],a,b,top];return Array.from({length:N+1},(_,i)=>{const v=i/N;let k=1;while(k<3&&v>stations[k])k++;const f=(v-stations[k-1])/(stations[k]-stations[k-1]),slack=(1-s.controls.rig.shrouds/100)*.10*Math.sin(Math.PI*f),p=anchors[k-1].map((x,j)=>lerp(x,anchors[k][j],f));p[0]+=side*slack;p[1]-=slack*.25;return p;});}
export function shroudAtHeight(s,side,y){const points=shroudPath(s,side,24);let k=1;while(k<points.length-1&&points[k][1]<y)k++;const a=points[k-1],b=points[k],f=clamp((y-a[1])/(b[1]-a[1]));return a.map((x,i)=>lerp(x,b[i],f));}

const luffCache=new WeakMap();
export function headsailLuffPoint(v,s){const response=rigResponse(s),length=sailDesign('genoa',s).HLU/boatScale(s);let cached=luffCache.get(s);if(!cached||cached.response!==response||cached.length!==length){const points=Array.from({length:49},(_,i)=>forestayPoint(i/48,s)),arcs=[0];for(let i=1;i<points.length;i++)arcs.push(arcs.at(-1)+V.length(V.sub(points[i],points[i-1])));cached={response,length,arcs,total:arcs.at(-1),samples:new Map()};luffCache.set(s,cached);}if(cached.samples.has(v))return [...cached.samples.get(v)];const target=clamp(v)*(sailDesign('genoa',s).exploratory?length:Math.min(length,cached.total));if(target>cached.total){const top=forestayPoint(1,s),axis=V.unit(V.sub(top,forestayPoint(.98,s))),point=V.add(top,V.mul(axis,target-cached.total));cached.samples.set(v,point);return [...point];}let a=0,b=48;while(b-a>1){const i=(a+b)>>1;if(cached.arcs[i]<target)a=i;else b=i;}const f=(target-cached.arcs[a])/Math.max(1e-12,cached.arcs[b]-cached.arcs[a]);const point=forestayPoint((a+f)/48,s);cached.samples.set(v,point);return [...point];}
